function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),2200)}
function norm(s){return String(s||'').toLowerCase().replace(/cm\^?2|cm²|squareunits?|square units?|cm|degrees?|°|edges?|holes?|pages?|units?|candles?|tiles?/g,'').replace(/\s|,|\$/g,'').replace(/×/g,'x').trim()}
function answerOK(ans,answers){const a=norm(ans);return answers.some(x=>a===norm(x))}

