function problem(o){return o}
const bank=[
 problem({id:'A1',room:'A',difficulty:'challenge',time:'4–5 min',source:'AMO 2016 Primary 6 Q12',type:'RAW',q:{en:'A pyramid has 7 vertices, 12 edges, and 7 faces, one of which is a hexagon. At least one edge on every face must be colored red. What is the least number of edges that must be colored red?',id:'Sebuah piramida memiliki 7 titik sudut, 12 rusuk, dan 7 sisi, salah satunya berbentuk segi enam. Setiap sisi harus memiliki sedikitnya satu rusuk berwarna merah. Berapa paling sedikit rusuk yang harus diwarnai merah?'},answers:['4'],hint:{en:'Focus on face adjacency. A top view makes it easier to see when one edge belongs to two neighboring triangular faces.',id:'Fokus pada sisi-sisi yang berbagi rusuk. Tampak atas memudahkan kita melihat kapan satu rusuk dimiliki dua sisi segitiga yang bersebelahan.'},solution:{en:'Three well-spaced side edges can cover all six triangular faces. One additional hexagon edge covers the base, so the minimum is 4.',id:'Tiga rusuk samping yang dipilih dengan tepat dapat mencakup keenam sisi segitiga. Satu rusuk segi enam tambahan mencakup alas, jadi minimum 4.'},trap:{en:'Giving every face its own separate edge.',id:'Memberi setiap sisi satu rusuk terpisah.'}}),
 problem({id:'A3',room:'A',difficulty:'challenge',time:'4–5 min',source:'AMO 2017 Primary 6 Q13',type:'RAW',q:{en:'Triangle PQR is isosceles with PQ=QR. B lies on PR and A lies on PQ. AB is extended to C on extended QR. Triangle BRC is also isosceles with BR=RC, and angle C=24°. Find angle QAC.',id:'Segitiga PQR sama kaki dengan PQ=QR. B berada pada PR dan A pada PQ. AB diperpanjang ke C pada perpanjangan QR. Segitiga BRC juga sama kaki dengan BR=RC, dan sudut C=24°. Tentukan sudut QAC.'},answers:['72'],hint:{en:'Turn the equal-side marks into equal base angles before calculating.',id:'Ubah tanda sisi sama panjang menjadi sudut alas yang sama sebelum menghitung.'},solution:{en:'BRC has base angles 24°, so angle BRC=132° and adjacent QRB=48°. PQR has base angles 48°, so angle Q=84°. Thus QAC=180−84−24=72°.',id:'BRC memiliki sudut alas 24°, sehingga ∠BRC=132° dan sudut bersebelahan QRB=48°. PQR memiliki sudut alas 48°, sehingga sudut Q=84°. Maka QAC=180−84−24=72°.'},trap:{en:'Using the diagram as decoration instead of marking implied equal angles.',id:'Melihat gambar hanya sebagai ilustrasi tanpa menandai sudut-sudut sama yang tersirat.'}}),
 problem({id:'A4',room:'A',difficulty:'core',time:'1–2 min',source:'AMO 2016 Primary 6 Q3',type:'RAW',q:{en:'How many square units bigger is a 6×6 square than a 5×5 square?',id:'Berapa satuan persegi selisih luas persegi 6×6 dan persegi 5×5?'},answers:['11'],hint:{en:'Place the smaller square inside the larger and look at the remaining border.',id:'Letakkan persegi kecil di dalam persegi besar dan perhatikan bagian tepi yang tersisa.'},solution:{en:'The border is a 6×1 strip plus a 5×1 strip: 6+5=11.',id:'Bagian tepi dapat dipecah menjadi strip 6×1 dan 5×1: 6+5=11.'},trap:{en:'Answering 1 because the side lengths differ by 1.',id:'Menjawab 1 hanya karena panjang sisinya berbeda 1.'}}),
 problem({id:'A6',room:'A',difficulty:'challenge',time:'3–4 min',source:'AMO 2016 Primary 6 Q20',type:'RAW',q:{en:'Joseph lit 1/4 of the candles on a cake. Then he lit 5 more candles, and exactly 1/3 of all the candles were lit. How many candles were on the cake?',id:'Joseph menyalakan 1/4 dari seluruh lilin pada kue. Lalu ia menyalakan 5 lilin lagi sehingga tepat 1/3 dari seluruh lilin menyala. Berapa jumlah seluruh lilin?'},answers:['60'],hint:{en:'Draw one bar in twelfths so 1/4 and 1/3 use the same visual scale.',id:'Gambar satu batang yang dibagi menjadi dua belas bagian agar 1/4 dan 1/3 berada pada skala visual yang sama.'},solution:{en:'1/4=3/12 and 1/3=4/12. The extra 1/12 equals 5 candles, so the whole is 12×5=60.',id:'1/4=3/12 dan 1/3=4/12. Tambahan 1/12 sama dengan 5 lilin, jadi seluruhnya 12×5=60.'},trap:{en:'Subtracting the fractions without representing what the 5 candles mean.',id:'Mengurangkan pecahan tanpa menunjukkan bagian yang diwakili oleh 5 lilin.'}}),
 problem({id:'B1',room:'B',difficulty:'challenge',time:'4–5 min',source:'AMO 2017 Primary 6 Q2',type:'RAW',q:{en:'Rectangles ABCD and EFGH overlap in a rectangle. Their areas are 174 cm² and 52 cm². EF=13 cm and BC=29 cm. Find the area of the entire combined figure.',id:'Persegi panjang ABCD dan EFGH saling bertumpuk membentuk daerah tumpang tindih berbentuk persegi panjang. Luasnya 174 cm² dan 52 cm². EF=13 cm dan BC=29 cm. Tentukan luas seluruh gabungan.'},answers:['202'],hint:{en:'Find the missing width of each rectangle, then identify the shared rectangle that was counted twice.',id:'Cari lebar yang belum diketahui dari masing-masing persegi panjang, lalu tentukan daerah yang terhitung dua kali.'},solution:{en:'52÷13=4 and 174÷29=6, so overlap=4×6=24. Union=174+52−24=202.',id:'52÷13=4 dan 174÷29=6, jadi daerah tumpang tindih=4×6=24. Luas gabungan=174+52−24=202.'},trap:{en:'Adding 174+52 without correcting the double-counted overlap.',id:'Menjumlahkan 174+52 tanpa mengoreksi daerah tumpang tindih yang terhitung dua kali.'}}),
 problem({id:'B2',room:'B',difficulty:'core',time:'2–3 min',source:'AMO 2016 Primary 6 Q10',type:'RAW',q:{en:'Two 13×17 rectangles overlap to form a 13×31 rectangle. What is the area of the overlap region?',id:'Dua persegi panjang 13×17 saling bertumpuk sehingga gabungannya menjadi persegi panjang 13×31. Berapa luas daerah tumpang tindih?'},answers:['39'],hint:{en:'The two 17-unit lengths total 34, but the union length is only 31.',id:'Dua panjang 17 berjumlah 34, tetapi panjang gabungannya hanya 31.'},solution:{en:'Overlap length=34−31=3, so area=13×3=39.',id:'Panjang daerah tumpang tindih=34−31=3, jadi luasnya=13×3=39.'},trap:{en:'Subtracting areas before understanding the repeated length.',id:'Langsung mengurangkan luas sebelum memahami panjang yang berulang.'}}),
 problem({id:'B3',room:'B',difficulty:'advanced',time:'5–6 min',source:'AMO 2016 Primary 6 Q14',type:'RAW',q:{en:'Two 6 cm by 10 cm rectangles overlap to form an 8-sided shape. The overlap is a rectangle with counting-number side lengths. What is the least possible perimeter of the 8-sided shape?',id:'Dua persegi panjang 6 cm × 10 cm saling bertumpuk membentuk bangun bersisi 8. Daerah tumpang tindih berupa persegi panjang dengan panjang sisi bilangan cacah. Berapa keliling paling kecil yang mungkin?'},answers:['36'],hint:{en:'Start from the sum of the two rectangle perimeters and ask which boundary becomes internal.',id:'Mulai dari jumlah keliling kedua persegi panjang dan tentukan bagian batas mana yang menjadi bagian dalam.'},solution:{en:'Separate perimeters total 64. The largest proper counting-number overlap is 9×5 with perimeter 28, which becomes internal. 64−28=36 cm.',id:'Jumlah keliling saat terpisah 64. Overlap terbesar yang masih memenuhi syarat adalah 9×5 dengan keliling 28, dan batas itu menjadi bagian dalam. 64−28=36 cm.'},trap:{en:'Treating perimeter like area and assuming overlap behaves the same way.',id:'Memperlakukan keliling seperti luas dan menganggap daerah tumpang tindih bekerja dengan cara yang sama.'}}),
 problem({id:'B4',room:'B',difficulty:'core',time:'2–3 min',source:'AMO 2022 Grade 6 Mock-Up Q20',type:'RAW',q:{en:'Two identical rectangular cards partially overlap. The overlap is a square of area 4 cm², and the total area of the non-overlapping parts is 12 cm². What is the area of one card?',id:'Dua kartu persegi panjang identik saling bertumpuk. Daerah tumpang tindih berupa persegi dengan luas 4 cm², dan jumlah luas bagian yang tidak saling bertumpuk adalah 12 cm². Berapa luas satu kartu?'},answers:['10'],hint:{en:'The two whole cards contain the 12 cm² non-overlap plus two copies of the 4 cm² overlap.',id:'Dua kartu utuh terdiri dari 12 cm² bagian yang tidak saling bertumpuk ditambah dua salinan daerah tumpang tindih 4 cm².'},solution:{en:'Combined card areas=12+2×4=20, so one identical card has area 10 cm².',id:'Jumlah luas dua kartu=12+2×4=20, jadi satu kartu identik luasnya 10 cm².'},trap:{en:'Adding 12+4 and treating that as one card.',id:'Menjumlahkan 12+4 lalu menganggapnya sebagai luas satu kartu.'}}),
 problem({id:'B6',room:'B',difficulty:'challenge',time:'3–4 min',source:'AMO 2016 Primary 6 Q23',type:'LIGHTLY ADAPTED',q:{en:'Two identical 6×6×2 bricks are glued along one 2×6 face. All exposed faces are painted. What total area is painted?',id:'Dua balok identik 6×6×2 direkatkan pada satu bidang 2×6. Semua bidang yang tampak dicat. Berapa luas total yang dicat?'},answers:['216'],hint:{en:'Add the two separate surface areas, then remove the glued face twice.',id:'Jumlahkan luas permukaan kedua balok saat terpisah, lalu kurangi bidang yang direkatkan sebanyak dua kali.'},solution:{en:'One brick has surface area 120. Two give 240. Gluing hides two 2×6 faces: 240−24=216.',id:'Satu balok memiliki luas permukaan 120. Dua balok memberi 240. Perekat menyembunyikan dua bidang 2×6: 240−24=216.'},trap:{en:'Subtracting the contact area only once.',id:'Mengurangi luas bidang kontak hanya satu kali.'}}),
 problem({id:'C1',room:'C',difficulty:'challenge',time:'4–5 min',source:'AMO 2017 Primary 6 Q15',type:'RAW',q:{en:'A 4×4×4 cube is cut into two identical rectangular solids. One half is flipped and placed tightly side-by-side with the other. What is the total surface area of the new solid?',id:'Sebuah kubus 4×4×4 dipotong menjadi dua balok identik. Satu bagian dibalik lalu diletakkan rapat di samping bagian lain. Berapa luas permukaan bangun baru?'},answers:['112'],hint:{en:'Reconstruct the final solid first. Each half is 4×4×2.',id:'Susun bentuk akhirnya terlebih dahulu. Setiap bagian berukuran 4×4×2.'},solution:{en:'The new solid is an 8×4×2 cuboid. Surface area=2(32+16+8)=112.',id:'Bangun baru adalah balok 8×4×2. Luas permukaan=2(32+16+8)=112.'},trap:{en:'Assuming rearrangement preserves surface area.',id:'Menganggap penyusunan ulang mempertahankan luas permukaan.'}}),
 problem({id:'C2',room:'C',difficulty:'challenge',time:'3–4 min',source:'AMO 2022 Grade 6 Mock-Up Q19',type:'RAW',q:{en:'A steel cuboid measuring 270 cm by 100 cm by 64 cm is reshaped into a cube. Find the sum of the digits of the cube’s surface area.',id:'Balok baja berukuran 270 cm × 100 cm × 64 cm dibentuk ulang menjadi kubus. Tentukan jumlah digit dari luas permukaan kubus.'},answers:['18'],hint:{en:'The same steel preserves volume, not surface area.',id:'Baja yang sama mempertahankan volume, bukan luas permukaan.'},solution:{en:'Volume=1,728,000=120³, so cube side=120. Surface area=86,400 and digit sum=18.',id:'Volume=1.728.000=120³, jadi sisi kubus=120. Luas permukaan=86.400 dan jumlah digit=18.'},trap:{en:'Preserving the original surface area instead of volume.',id:'Mempertahankan luas permukaan semula, bukan volume.'}}),
 problem({id:'C3',room:'C',difficulty:'core',time:'2–3 min',source:'AMO 2019 Primary 6 Q7',type:'RAW',q:{en:'Jessica folds a rectangle in half, then folds it in half again to form a 6 cm by 6 cm square. What is the area of the original rectangle?',id:'Jessica melipat persegi panjang menjadi dua, lalu melipatnya menjadi dua lagi hingga menjadi persegi 6 cm × 6 cm. Berapa luas persegi panjang semula?'},answers:['144'],hint:{en:'Work backward with area. Each unfold doubles the area.',id:'Kerja mundur menggunakan luas. Setiap membuka satu lipatan menggandakan luas.'},solution:{en:'36→72→144 cm².',id:'36→72→144 cm².'},trap:{en:'Trying to guess the original side lengths first.',id:'Mencoba menebak panjang sisi awal terlebih dahulu.'}}),
 problem({id:'C4',room:'C',difficulty:'advanced',time:'5–6 min',source:'AMO 2018 Primary 6 Q17',type:'RAW',q:{en:'Four right triangles have leg lengths 1×4, 2×4, 3×4, and 4×4 cm. Without overlap, what is the smallest whole-number area of a rectangle that can contain all four triangles?',id:'Empat segitiga siku-siku memiliki pasangan kaki 1×4, 2×4, 3×4, dan 4×4 cm. Tanpa saling tumpang tindih, berapa luas bilangan bulat terkecil dari persegi panjang yang dapat memuat semuanya?'},answers:['24'],hint:{en:'Total area gives a lower bound, but you must also test whether the pieces can actually fit.',id:'Jumlah luas memberi batas bawah, tetapi kamu juga harus mengecek apakah semua bagian benar-benar dapat disusun.'},solution:{en:'Total triangle area is 20. A 5×4 rectangle has area 20 but cannot fit the pieces; a 6×4 rectangle can. Minimum area=24.',id:'Jumlah luas segitiga adalah 20. Persegi panjang 5×4 memiliki luas 20 tetapi tidak dapat memuat susunannya; 6×4 dapat. Luas minimum=24.'},trap:{en:'Assuming the area lower bound is automatically achievable.',id:'Menganggap batas bawah luas pasti dapat dicapai.'}}),
 problem({id:'D1',room:'D',difficulty:'challenge',time:'4–5 min',source:'AMO 2022 Grade 6 Mock-Up Q11',type:'RAW',q:{en:'A triangular sheet is folded several times and punched in its folded state. When the paper is completely opened, which hole pattern is formed?',id:'Selembar kertas segitiga dilipat beberapa kali lalu dilubangi ketika masih terlipat. Ketika dibuka sepenuhnya, pola lubang mana yang terbentuk?'},answers:['d','optiond','opsid'],hint:{en:'Undo the most recent fold first. Each unfold reflects every current hole across that fold line.',id:'Balikkan lipatan paling baru terlebih dahulu. Setiap pembukaan lipatan mencerminkan semua lubang yang ada terhadap garis lipatan tersebut.'},solution:{en:'Reverse the folds one at a time in the opposite order. The final pattern matches source option D.',id:'Balikkan lipatan satu per satu dalam urutan terbalik. Pola akhirnya sesuai opsi D pada sumber.'},trap:{en:'Trying to imagine the fully unfolded sheet in one jump.',id:'Mencoba membayangkan kertas terbuka penuh dalam satu langkah.'}}),
 problem({id:'D2',room:'D',difficulty:'core',time:'2–3 min',source:'AMO 2018 Mock Test #1 Grade 6 Q6',type:'STRUCTURAL VARIANT',q:{en:'Triangle ABC has A(1,1), B(2,4), C(4,2). Reflect it across x=5. Give A′, B′, and C′.',id:'Segitiga ABC memiliki A(1,1), B(2,4), C(4,2). Cerminkan terhadap garis x=5. Tentukan A′, B′, dan C′.'},answers:['(9,1)(8,4)(6,2)','9,1;8,4;6,2','a9,1b8,4c6,2','a′(9,1)b′(8,4)c′(6,2)','a(9,1)b(8,4)c(6,2)'],hint:{en:'Keep y fixed and preserve horizontal distance from x=5.',id:'Pertahankan nilai y dan jaga jarak horizontal terhadap x=5.'},solution:{en:'x maps to 10−x: A′(9,1), B′(8,4), C′(6,2).',id:'x berubah menjadi 10−x: A′(9,1), B′(8,4), C′(6,2).'},trap:{en:'Reflecting from the y-axis instead of x=5.',id:'Mencerminkan terhadap sumbu-y, bukan garis x=5.'}}),
 problem({id:'D5',room:'D',difficulty:'core',time:'2–3 min',source:'AMO 2022 Grade 6 Mock-Up Q11',type:'STRUCTURAL VARIANT',q:{en:'A square sheet is folded in half vertically and then in half horizontally. One hole is punched away from both fold lines. How many holes appear after complete unfolding?',id:'Selembar kertas persegi dilipat dua secara vertikal lalu dua secara horizontal. Satu lubang dibuat jauh dari kedua garis lipatan. Berapa lubang muncul setelah dibuka sepenuhnya?'},answers:['4'],hint:{en:'Undo one fold at a time. The first unfold makes two holes; the second reflects both.',id:'Buka satu lipatan setiap kali. Pembukaan pertama menghasilkan dua lubang; pembukaan kedua mencerminkan keduanya.'},solution:{en:'1→2→4 holes.',id:'1→2→4 lubang.'},trap:{en:'Doubling only once.',id:'Hanya menggandakan sekali.'}}),
 problem({id:'E1',room:'E',difficulty:'core',time:'3–4 min',source:'AMO 2018 Mock Test #1 Grade 6 Q12',type:'STRUCTURAL VARIANT',q:{en:'Five unit cubes are joined: three in a row, one on top of the middle cube, and one directly behind the middle cube. What is the surface area?',id:'Lima kubus satuan disusun: tiga berjajar, satu di atas kubus tengah, dan satu tepat di belakang kubus tengah. Berapa luas permukaannya?'},answers:['22'],hint:{en:'Start from 30 separate faces and count face-to-face contacts. Each contact hides 2 faces.',id:'Mulai dari 30 bidang saat terpisah lalu hitung bidang yang saling bersentuhan. Setiap kontak menyembunyikan 2 bidang.'},solution:{en:'There are 4 contacts, so surface area=30−2×4=22.',id:'Ada 4 kontak, jadi luas permukaan=30−2×4=22.'},trap:{en:'Counting only faces visible from one viewpoint.',id:'Menghitung hanya bidang yang terlihat dari satu sudut pandang.'}}),
 problem({id:'E2',room:'E',difficulty:'core',time:'2–3 min',source:'AMO 2017 Primary 6 Q23',type:'STRUCTURAL VARIANT',q:{en:'A 4×4×4 cube is made of unit cubes. One unit cube is removed from a corner. What is the new surface area?',id:'Kubus 4×4×4 tersusun dari kubus satuan. Satu kubus satuan pada sudut diambil. Berapa luas permukaan baru?'},answers:['96'],hint:{en:'Compare the 3 outside faces lost with the 3 previously hidden faces that become exposed.',id:'Bandingkan 3 bidang luar yang hilang dengan 3 bidang yang sebelumnya tersembunyi lalu menjadi terbuka.'},solution:{en:'Original surface area=96. Net change is −3+3=0, so it remains 96.',id:'Luas permukaan awal=96. Perubahan bersih −3+3=0, jadi tetap 96.'},trap:{en:'Subtracting the removed cube’s outside faces without adding newly exposed faces.',id:'Mengurangi bidang luar kubus yang diambil tanpa menambahkan bidang baru yang terbuka.'}}),
 problem({id:'E4',room:'E',difficulty:'core',time:'2–3 min',source:'AMO 2022 Grade 6 Mock-Up Q19',type:'STRUCTURAL VARIANT',q:{en:'A solid 40 cm by 25 cm by 8 cm cuboid is melted and reshaped into a cube. What is the edge length of the cube?',id:'Balok padat 40 cm × 25 cm × 8 cm dilelehkan lalu dibentuk menjadi kubus. Berapa panjang rusuk kubus?'},answers:['20'],hint:{en:'Preserve volume: 40×25×8=8000.',id:'Pertahankan volume: 40×25×8=8000.'},solution:{en:'8000=20³, so the cube edge is 20 cm.',id:'8000=20³, jadi panjang rusuk kubus 20 cm.'},trap:{en:'Preserving surface area instead of volume.',id:'Mempertahankan luas permukaan, bukan volume.'}}),
 problem({id:'F1',room:'F',difficulty:'core',time:'2–3 min',source:'AMO 2022 Grade 6 Mock-Up Q9',type:'LIGHTLY ADAPTED',q:{en:'On a 3×3 lattice of points, move from bottom-left to top-right using only right or up shortest moves. How many shortest paths are there?',id:'Pada kisi 3×3 titik, bergerak dari kiri bawah ke kanan atas hanya dengan langkah ke kanan atau ke atas yang terpendek. Ada berapa jalur terpendek?'},answers:['6'],hint:{en:'Every shortest path uses exactly two R moves and two U moves. Organize the orders.',id:'Setiap jalur terpendek memakai tepat dua langkah R dan dua langkah U. Susun urutannya secara sistematis.'},solution:{en:'The six orders are RRUU, RURU, RUUR, URRU, URUR, UURR.',id:'Enam urutannya: RRUU, RURU, RUUR, URRU, URUR, UURR.'},trap:{en:'Drawing paths randomly and missing one.',id:'Menggambar jalur secara acak sehingga ada yang terlewat.'}}),
 problem({id:'F4',room:'F',difficulty:'core',time:'2–3 min',source:'AMO 2018 Mock Test #1 Grade 6 Q4',type:'STRUCTURAL VARIANT',q:{en:'How many squares of all sizes are in a 3×3 square grid?',id:'Berapa banyak persegi dari semua ukuran yang terdapat pada kisi persegi 3×3?'},answers:['14'],hint:{en:'Count by size: 1×1, then 2×2, then 3×3.',id:'Hitung berdasarkan ukuran: 1×1, lalu 2×2, lalu 3×3.'},solution:{en:'9+4+1=14.',id:'9+4+1=14.'},trap:{en:'Counting only the 9 smallest squares.',id:'Menghitung hanya 9 persegi terkecil.'}}),
 problem({id:'F6',room:'F',difficulty:'advanced',time:'5–6 min',source:'AMO 2017 Primary 6 Q25',type:'STRUCTURAL VARIANT',q:{en:'A 5×5 square grid has the center unit square shaded. How many squares of any size do NOT include the shaded square?',id:'Kisi persegi 5×5 memiliki satu persegi satuan di tengah yang diarsir. Berapa banyak persegi dari semua ukuran yang TIDAK memuat persegi diarsir itu?'},answers:['36'],hint:{en:'Use complement: total squares minus squares containing the center cell, organized by size.',id:'Gunakan komplemen: semua persegi dikurangi persegi yang memuat sel tengah, disusun berdasarkan ukuran.'},solution:{en:'Total=55. Containing-center counts by size are 1,4,9,4,1 for total 19. So 55−19=36.',id:'Total=55. Banyak persegi yang memuat sel tengah berdasarkan ukuran adalah 1,4,9,4,1, total 19. Jadi 55−19=36.'},trap:{en:'Trying to count valid squares directly without a systematic complement.',id:'Mencoba menghitung persegi valid secara langsung tanpa komplemen yang sistematis.'}}),
];

function navHead(sec){return `<div class="section-head"><div><span class="section-kicker">${state.lang==='en'?'AMO 2026 · VISUAL REASONING LAB':'AMO 2026 · LAB PENALARAN VISUAL'}</span><h1>${esc(i18n(sec.title))}</h1><p>${esc(i18n(sec.short))}</p></div><img class="mascot-mini" src="${ASSET(sec.mascot)}" alt="" /></div>`}
function navFoot(){const isDone=state.completed.includes(state.section);return `<div class="nav-row"><button class="outline-btn" data-nav="prev" ${state.section===0?'disabled':''}>← ${t('prev')}</button><button class="soft-btn" data-complete>${isDone?'✓ '+t('done'):t('complete')}</button><button class="primary-btn" data-nav="next" ${state.section===sections.length-1?'disabled':''}>${t('next')} →</button></div>`}
function mascot(file,en,id){return `<div class="mascot-inline"><img src="${ASSET(file)}" alt=""><p>${esc(state.lang==='en'?en:id)}</p></div>`}

function renderHome(){const count=state.completed.length;return `<div class="page"><section class="visual-lab-hero"><div><span class="eyebrow">${state.lang==='en'?'AMO 2026 PREPARATION':'PERSIAPAN AMO 2026'}</span><h1>${state.lang==='en'?'Strategy Trainer III':'Pelatih Strategi III'}</h1><p class="lead">${state.lang==='en'?'VISUAL REASONING LAB · Geometry is the vehicle. The real target is learning to improve the picture before increasing the calculation.':'LAB PENALARAN VISUAL · Geometri adalah medianya. Target utamanya adalah memperbaiki cara melihat gambar sebelum menambah hitungan.'}</p><div class="routine">${state.lang==='en'?'LOOK → MARK → RESTRUCTURE → SOLVE → CHECK':'LIHAT → TANDAI → SUSUN ULANG → SELESAIKAN → CEK'}</div><div class="hero-actions"><button class="primary-btn" data-start>${state.completed.length?t('resume'):t('start')}</button></div></div><img src="${ASSET('sheet2_top_04.png')}" alt=""></section><div class="visual-rhythm"><div><b>${state.lang==='en'?'LOOK':'LIHAT'}</b><span>${state.lang==='en'?'Read the visual':'Baca gambarnya'}</span></div><div><b>${state.lang==='en'?'MARK':'TANDAI'}</b><span>${state.lang==='en'?'Externalize givens':'Tandai informasi yang diberikan'}</span></div><div><b>${state.lang==='en'?'RESTRUCTURE':'SUSUN ULANG'}</b><span>${state.lang==='en'?'Redraw · split · reflect':'Gambar ulang · pecah · cerminkan'}</span></div><div><b>${state.lang==='en'?'CHECK':'CEK'}</b><span>${state.lang==='en'?'Return to the figure':'Kembali ke gambar'}</span></div></div><div class="panel"><div class="label">${state.lang==='en'?'Lesson map':'Peta pelajaran'}</div><div class="menu-grid">${sections.map(s=>`<button class="menu-card ${state.completed.includes(s.id)?'done':''}" data-open="${s.id}"><span class="status">${state.completed.includes(s.id)?'✓':String(s.id+1).padStart(2,'0')}</span><small>${s.icon}</small><h3>${esc(i18n(s.title))}</h3><p>${esc(i18n(s.short))}</p></button>`).join('')}</div><p class="source-line">${count}/${sections.length} ${t('progress')}</p></div></div>`}

function renderMap(){return `<div class="page">${navHead(sections[0])}<div class="lesson-stack"><div class="panel teal"><div class="label">${t('mainIdea')}</div><h2>${state.lang==='en'?'The picture is part of the reasoning.':'Gambar adalah bagian dari penalaran.'}</h2><p class="lead">${state.lang==='en'?'When the diagram feels hard, do not ask only “Which formula?” Ask: “Is this the best picture to think with?”':'Saat gambar terasa sulit, jangan hanya bertanya “Rumus apa?” Tanyakan: “Apakah ini gambar terbaik untuk berpikir?”'}</p></div><div class="visual-toolkit">${tools.map((x,i)=>`<div class="visual-tool ${i>=6?'new':''}"><strong>${state.lang==='en'?x[0]:x[1]}</strong><small>${state.lang==='en'?x[2]:x[3]}</small></div>`).join('')}</div>${mascot('sheet2_bottom_02.png', 'A visual move is useful only when it exposes structure or reduces work.', 'Langkah visual berguna hanya jika membuat struktur lebih jelas atau mengurangi pekerjaan.')}<div class="panel gold"><div class="label">${t('why')}</div><p>${state.lang==='en'?'Trainer III does not replace the earlier strategies. It combines naturally with them: Represent + Visualize, Organize + visual counting, What Stays Fixed + reconstruct, Work Backward + folding, Eliminate + geometric constraints.':'Trainer III tidak menggantikan strategi sebelumnya. Strategi ini digabungkan secara alami: Representasi + Visualisasi, Organisasi + hitung visual, Cari yang Tetap + susun ulang, Kerja Mundur + lipatan, Eliminasi + syarat geometri.'}</p></div></div>${navFoot()}</div>`}

function pyramidSVG(){const top=state.visualize.view==='top';if(!top)return `<svg viewBox="0 0 620 350" role="img" aria-label="${state.lang==='en'?'Perspective drawing of a pyramid with hexagonal base. No answer edges are marked.':'Gambar perspektif piramida dengan alas segi enam. Tidak ada rusuk jawaban yang ditandai.'}"><polygon points="185,255 255,300 365,300 435,255 395,220 225,220" fill="#f9fcfd" stroke="#31596b" stroke-width="3"/><circle cx="310" cy="48" r="4" fill="#31596b"/>${[[310,48,185,255],[310,48,255,300],[310,48,365,300],[310,48,435,255],[310,48,395,220],[310,48,225,220]].map(a=>`<line x1="${a[0]}" y1="${a[1]}" x2="${a[2]}" y2="${a[3]}" stroke="#31596b" stroke-width="3"/>`).join('')}<text x="310" y="332" text-anchor="middle" class="muted">${state.lang==='en'?'7 vertices · 12 edges · 7 faces (one hexagon)':'7 titik sudut · 12 rusuk · 7 sisi (satu segi enam)'}</text></svg>`;
 const cx=310,cy=175,r=115;let pts=[];for(let i=0;i<6;i++){const ang=(-90+i*60)*Math.PI/180;pts.push([cx+r*Math.cos(ang),cy+r*Math.sin(ang)])}
 let edges=[];for(let i=0;i<6;i++){const j=(i+1)%6;edges.push({id:`b${i}`,x1:pts[i][0],y1:pts[i][1],x2:pts[j][0],y2:pts[j][1],kind:'base'});edges.push({id:`s${i}`,x1:cx,y1:cy,x2:pts[i][0],y2:pts[i][1],kind:'side'})}
 return `<svg viewBox="0 0 620 350" role="img" aria-label="${state.lang==='en'?'Neutral top-view adjacency model. Candidate edges can be selected.':'Model tampak atas netral. Rusuk kandidat dapat dipilih.'}"><polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="#fbfdfd" stroke="#9bb0b9" stroke-width="2"/>${edges.map(e=>`<line class="selectable ${state.visualize.selected.includes(e.id)?'selected':''}" data-edge="${e.id}" x1="${e.x1}" y1="${e.y1}" x2="${e.x2}" y2="${e.y2}" stroke="#31596b" stroke-width="4" stroke-linecap="round"/>`).join('')}<circle cx="${cx}" cy="${cy}" r="6" fill="#31596b"/><text x="310" y="325" text-anchor="middle" class="muted">${state.lang==='en'?'Select candidate edges. Nothing is pre-highlighted.':'Pilih rusuk kandidat. Tidak ada jawaban yang ditandai sebelumnya.'}</text></svg>`}
function checkPyramid(){const S=new Set(state.visualize.selected);let tri=true;for(let i=0;i<6;i++){if(!(S.has(`b${i}`)||S.has(`s${i}`)||S.has(`s${(i+1)%6}`)))tri=false}const base=[0,1,2,3,4,5].some(i=>S.has(`b${i}`));if(tri&&base&&S.size===4)toast(state.lang==='en'?'Excellent: all faces are covered with the minimum 4 edges.':'Bagus: semua sisi tercakup dengan minimum 4 rusuk.');else if(tri&&base)toast(state.lang==='en'?`All faces are covered, but ${S.size} edges are not minimal yet.`:`Semua sisi sudah tercakup, tetapi ${S.size} rusuk belum minimum.`);else toast(state.lang==='en'?'Some face is still uncovered. Check adjacency again.':'Masih ada sisi yang belum tercakup. Cek hubungan berbagi rusuk lagi.')}
function renderVisualize(){return `<div class="page">${navHead(sections[1])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'A correct diagram can still be a poor solving representation.':'Gambar yang benar belum tentu menjadi representasi terbaik untuk menyelesaikan soal.'}</h3><p>${state.lang==='en'?'The pyramid perspective hides which faces share an edge. What matters here is adjacency, not lengths or angles.':'Perspektif piramida menyembunyikan sisi mana yang berbagi rusuk. Yang penting di sini adalah hubungan antar-sisi, bukan panjang atau sudut.'}</p></div><div class="stage-grid"><div class="visual-stage">${pyramidSVG()}<div class="view-toggle"><button data-view="perspective" class="${state.visualize.view==='perspective'?'active':''}">${state.lang==='en'?'Perspective':'Perspektif'}</button><button data-view="top" class="${state.visualize.view==='top'?'active':''}">${state.lang==='en'?'Neutral top view':'Tampak atas netral'}</button>${state.visualize.view==='top'?`<button data-check-pyramid>${t('check')}</button><button data-reset-pyramid>${t('reset')}</button>`:''}</div></div><div class="focus-panel formal"><div class="label">${t('guide')}</div><p><strong>${state.lang==='en'?'Problem:':'Soal:'}</strong> ${esc(i18n(bank[0].q))}</p><p>${state.lang==='en'?'Ask first: What relationship is difficult to see? Could one selected edge serve two faces at once?':'Tanya dulu: Hubungan apa yang sulit terlihat? Bisakah satu rusuk yang dipilih melayani dua sisi sekaligus?'}</p>${mascot('sheet1_top_03.png','Try changing the viewpoint before changing the arithmetic.','Coba ubah sudut pandang sebelum menambah hitungan.')}</div></div><div class="focus-panel turn"><div class="label">${t('yourTurn')}</div><p>${state.lang==='en'?'How many square units bigger is a 6×6 square than a 5×5 square? First picture the 5×5 square inside the 6×6 square.':'Berapa satuan persegi selisih luas persegi 6×6 dan 5×5? Bayangkan dulu persegi 5×5 berada di dalam persegi 6×6.'}</p>${quickAnswer('inlineA4',['11'],state.lang==='en'?'Use the border, not just the side-length difference.':'Gunakan daerah tepinya, bukan hanya selisih panjang sisi.')}</div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'Do not assign a separate red edge to every face. That ignores shared edges and replaces structure with unnecessary counting.':'Jangan memberi satu rusuk merah terpisah untuk setiap sisi. Itu mengabaikan rusuk yang dipakai bersama dan mengganti struktur dengan hitungan yang tidak perlu.'}</p></div></div>${navFoot()}</div>`}

function overlapSVG(){const s=state.decompStep;return `<svg viewBox="0 0 660 360" role="img" aria-label="${state.lang==='en'?'Two rectangles crossing with a rectangular overlap; only given data are shown initially.':'Dua persegi panjang berpotongan dengan overlap berbentuk persegi panjang; awalnya hanya data yang diberikan yang ditampilkan.'}"><rect x="75" y="145" width="510" height="105" rx="4" fill="${s>=1?'#e8f5f8':'#fafcfd'}" fill-opacity=".85" stroke="#245c8a" stroke-width="3"/><rect x="285" y="55" width="90" height="255" rx="4" fill="${s>=1?'#f1ebfb':'#fafcfd'}" fill-opacity=".85" stroke="#6d49a8" stroke-width="3"/><rect x="285" y="145" width="90" height="105" fill="${s>=1?'#ffe9b9':'transparent'}" stroke="#d97706" stroke-width="${s>=1?3:1}"/><text x="95" y="175" class="given">${state.lang==='en'?'Area':'Luas'} ABCD = 174 cm²</text><text x="390" y="94" class="given">${state.lang==='en'?'Area':'Luas'} EFGH = 52 cm²</text><text x="84" y="270" class="given">BC = 29 cm</text><text x="387" y="290" class="given">EF = 13 cm</text>${s>=2?`<text x="330" y="132" text-anchor="middle" class="derived">6 cm</text><text x="387" y="202" class="derived">4 cm</text>`:''}${s>=3?`<text x="330" y="205" text-anchor="middle" class="derived">24 cm²</text>`:''}</svg>`}
function renderDecompose(){const step=state.decompStep;return `<div class="page">${navHead(sections[2])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'An unfamiliar outline is often made from familiar pieces.':'Bentuk luar yang tampak asing sering tersusun dari bagian-bagian yang familiar.'}</h3><p>${state.lang==='en'?'Instead of tracing the outside boundary, separate what belongs only to A, to both, and only to B.':'Daripada menelusuri batas luar, pisahkan bagian yang hanya milik A, bagian tumpang tindih, dan hanya milik B.'}</p></div><div class="stage-grid"><div class="visual-stage">${overlapSVG()}<div class="decomp-legend">${step>=1?`<span class="only-a">${state.lang==='en'?'ONLY A':'HANYA A'}</span><span class="overlap">${state.lang==='en'?'OVERLAP':'TUMPANG TINDIH'}</span><span class="only-b">${state.lang==='en'?'ONLY B':'HANYA B'}</span>`:''}</div><div class="micro-actions"><button data-decomp-next>${step===0?(state.lang==='en'?'Separate the regions':'Pisahkan daerah'):t('reveal')}</button><button data-decomp-reset>${t('reset')}</button></div></div><div class="focus-panel formal"><div class="label">${t('guide')}</div><p>${state.lang==='en'?'If we add 174 and 52 immediately, which region is counted twice? Would finding the overlap be easier than tracing the whole outside boundary?':'Jika 174 dan 52 langsung dijumlahkan, daerah mana yang terhitung dua kali? Apakah mencari daerah tumpang tindih lebih mudah daripada menelusuri seluruh batas luar?'}</p>${step>=2?`<p><strong>${state.lang==='en'?'Recovered side lengths:':'Panjang sisi yang diperoleh:'}</strong> 52÷13=4, 174÷29=6.</p>`:''}${step>=3?`<p><strong>${state.lang==='en'?'Daerah tumpang tindih:':'Daerah tumpang tindih:'}</strong> 4×6=24 cm². ${state.lang==='en'?'Now the union can be found without tracing the irregular outline.':'Sekarang luas gabungan dapat dicari tanpa menelusuri bentuk luar yang tidak beraturan.'}</p>`:''}</div></div><div class="focus-panel turn"><div class="label">${t('yourTurn')}</div><p>${state.lang==='en'?'Two 13×17 rectangles form a 13×31 union. What is the overlap area?':'Dua persegi panjang 13×17 membentuk gabungan 13×31. Berapa luas daerah tumpang tindih?'}</p>${quickAnswer('inlineB2',['39'],state.lang==='en'?'Compare 17+17 with the final length 31.':'Bandingkan 17+17 dengan panjang akhir 31.')}</div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'Adding the two rectangle areas without removing one copy of the overlap counts the shared region twice.':'Menjumlahkan luas kedua persegi panjang tanpa mengurangi satu salinan daerah tumpang tindih membuat daerah bersama terhitung dua kali.'}</p></div></div>${navFoot()}</div>`}

function reconstructVisual(){const on=state.reconstructStep>0;return `<div class="reconstruct-demo"><div class="solid-box"><div class="dims">4 × 4 × 4</div><p>${state.lang==='en'?'cut into two equal solids':'dipotong menjadi dua bagian sama'}</p></div><b>→</b><div class="solid-box ${on?'active':''}"><div class="dims">${on?'8 × 4 × 2':'4 × 4 × 2 + 4 × 4 × 2'}</div><p>${on?(state.lang==='en'?'reconstructed final cuboid':'balok akhir setelah disusun ulang'):(state.lang==='en'?'same pieces, not yet rebuilt':'bagian sama, belum disusun ulang')}</p></div></div>`}
function renderReconstruct(){return `<div class="page">${navHead(sections[3])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'Move the same pieces mentally, then identify what changed and what survived.':'Pindahkan bagian yang sama secara mental, lalu tentukan apa yang berubah dan apa yang tetap.'}</h3></div><div class="visual-stage">${reconstructVisual()}<div class="micro-actions"><button data-reconstruct>${state.reconstructStep? t('reset'):(state.lang==='en'?'Flip and rebuild the two halves':'Balik dan susun ulang dua bagian')}</button></div></div><div class="focus-panel formal"><div class="label">${t('why')}</div><p>${state.lang==='en'?'Rearrangement does not preserve surface area. A better route is to reconstruct the new solid first. The two 4×4×2 halves become an 8×4×2 cuboid.':'Penyusunan ulang tidak mempertahankan luas permukaan. Jalur yang lebih baik adalah menyusun bentuk barunya terlebih dahulu. Dua bagian 4×4×2 menjadi balok 8×4×2.'}</p><p>${state.lang==='en'?'A different reconstruction family preserves volume: when the same steel is reshaped, volume survives even though surface area changes.':'Pada keluarga susun ulang lain, volume dipertahankan: ketika bahan yang sama dibentuk ulang, volume tetap walaupun luas permukaan berubah.'}</p></div><div class="focus-panel turn"><div class="label">${t('yourTurn')}</div><p>${state.lang==='en'?'A 40×25×8 solid cuboid is melted and reshaped into a cube. What is the cube edge length?':'Balok padat 40×25×8 dilelehkan dan dibentuk menjadi kubus. Berapa panjang rusuk kubus?'}</p>${quickAnswer('inlineE4',['20'],state.lang==='en'?'Preserve volume, not surface area.':'Pertahankan volume, bukan luas permukaan.')}</div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'Do not assume the new arrangement has the same surface area. Ask what physical quantity truly survives the transformation.':'Jangan menganggap susunan baru memiliki luas permukaan yang sama. Tanyakan besaran fisik apa yang benar-benar tetap.'}</p></div></div>${navFoot()}</div>`}

function foldTriangleSVG(final=false){const pts=final?[[126,110],[148,135],[164,158],[360,214]]:[[126,110]];return `<svg viewBox="0 0 500 330" role="img" aria-label="${final?(state.lang==='en'?'Final unfolded triangle with four hole positions.':'Segitiga terbuka penuh dengan empat posisi lubang.'):(state.lang==='en'?'Folded triangular sheet with one punch; answer pattern hidden.':'Kertas segitiga terlipat dengan satu lubang; pola akhir disembunyikan.')}"><polygon points="250,35 70,300 430,300" fill="#fbfcfd" stroke="#31596b" stroke-width="3"/>${!final?`<line x1="120" y1="145" x2="380" y2="145" stroke="#8799a0" stroke-width="2" stroke-dasharray="8 7"/><line x1="250" y1="300" x2="150" y2="145" stroke="#8799a0" stroke-width="2" stroke-dasharray="8 7"/><line x1="250" y1="300" x2="350" y2="145" stroke="#8799a0" stroke-width="2" stroke-dasharray="8 7"/>`:''}${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="7" fill="white" stroke="#d9467d" stroke-width="4"/>`).join('')}</svg>`}
function renderSymmetry(){const s=state.symStep;return `<div class="page">${navHead(sections[4])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'A fold is a transformation. Unfolding is a sequence of reflections.':'Lipatan adalah transformasi. Membuka lipatan berarti melakukan serangkaian pencerminan.'}</h3><p>${state.lang==='en'?'Reverse one fold at a time in the opposite order. Predict before revealing the next state.':'Balikkan satu lipatan setiap kali dalam urutan terbalik. Prediksi dulu sebelum melihat keadaan berikutnya.'}</p></div><div class="stage-grid"><div class="visual-stage">${foldTriangleSVG(s>=3)}</div><div class="prediction-lock"><strong>${s===0?(state.lang==='en'?'Which fold should be undone first?':'Lipatan mana yang harus dibuka terlebih dahulu?'):s===1?(state.lang==='en'?'After one unfold, what happens to the current hole?':'Setelah satu lipatan dibuka, apa yang terjadi pada lubang yang ada?'):s===2?(state.lang==='en'?'Ready for the final reveal?':'Siap melihat keadaan akhir?'):(state.lang==='en'?'Final state revealed only after the reasoning sequence.':'Keadaan akhir baru ditampilkan setelah urutan penalaran.')}</strong>${s<3?`<div class="prediction-grid">${s===0?`<button data-sym-choice="last">${state.lang==='en'?'Most recent diagonal fold':'Lipatan diagonal paling baru'}</button><button data-sym-choice="first">${state.lang==='en'?'First horizontal fold':'Lipatan horizontal pertama'}</button><button data-sym-choice="all">${state.lang==='en'?'All folds at once':'Semua lipatan sekaligus'}</button>`:s===1?`<button data-sym-choice="reflect">${state.lang==='en'?'It gains a reflected partner':'Muncul pasangan hasil pencerminan'}</button><button data-sym-choice="stay">${state.lang==='en'?'It stays as one hole':'Tetap satu lubang'}</button>`:`<button data-sym-choice="reveal">${state.lang==='en'?'Reflect the current set again, one fold at a time':'Cerminkan kumpulan lubang lagi, satu lipatan setiap kali'}</button>`}</div>`:`<p><strong>${state.lang==='en'?'Canonical result: source option D.':'Hasil kanonis: opsi D pada sumber.'}</strong></p>`}<div class="micro-actions"><button data-sym-reset>${t('reset')}</button></div></div></div><div class="focus-panel formal"><div class="label">${t('why')}</div><p>${state.lang==='en'?'Symmetry is a mapping rule, not just a visual property. The distance to the fold line is preserved, and every current hole must be reflected when that fold is undone.':'Simetri adalah aturan pemetaan, bukan sekadar sifat gambar. Jarak terhadap garis lipatan dipertahankan, dan setiap lubang yang ada harus dicerminkan saat lipatan itu dibuka.'}</p></div><div class="focus-panel turn"><div class="label">${t('yourTurn')}</div><p>${state.lang==='en'?'A square is folded in half vertically and then horizontally. One punch is away from both fold lines. How many holes appear after complete unfolding?':'Sebuah persegi dilipat dua secara vertikal lalu horizontal. Satu lubang dibuat jauh dari kedua garis lipatan. Berapa lubang muncul setelah dibuka sepenuhnya?'}</p>${quickAnswer('inlineD5',['4'],state.lang==='en'?'Undo one fold at a time: 1→2→?':'Buka satu lipatan setiap kali: 1→2→?')}</div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'Trying to imagine the fully unfolded paper in one jump overloads spatial working memory.':'Mencoba membayangkan kertas langsung terbuka penuh membuat beban visual terlalu besar dan mudah menimbulkan kesalahan pencerminan.'}</p></div></div>${navFoot()}</div>`}

function cubeStackSVG(){return `<svg viewBox="0 0 620 330" role="img" aria-label="${state.lang==='en'?'Schematic stack of five unit cubes. Contact count is not labeled.':'Skema susunan lima kubus satuan. Jumlah bidang kontak tidak ditampilkan.'}"><g stroke="#31596b" stroke-width="2.5" fill="#dff1f4">${[[100,190],[190,190],[280,190],[190,100],[190,245]].map((p,i)=>`<rect x="${p[0]}" y="${p[1]}" width="80" height="80" rx="3" fill="${i===4?'#eff6f8':'#dff1f4'}"/>`).join('')}</g><text x="310" y="306" text-anchor="middle" class="muted">${state.lang==='en'?'Schematic contact model — count face-to-face contacts, not just visible faces.':'Model kontak skematis — hitung bidang yang bersentuhan, bukan hanya yang terlihat.'}</text></svg>`}
function gridSVG(n=3,shaded=false){const size=240,x=90,y=45,cell=size/n;let lines='';for(let i=0;i<=n;i++){lines+=`<line x1="${x+i*cell}" y1="${y}" x2="${x+i*cell}" y2="${y+size}" stroke="#78909a"/><line x1="${x}" y1="${y+i*cell}" x2="${x+size}" y2="${y+i*cell}" stroke="#78909a"/>`}let sh='';if(shaded){const c=Math.floor(n/2);sh=`<rect x="${x+c*cell}" y="${y+c*cell}" width="${cell}" height="${cell}" fill="#f1d5df"/>`};return `<svg viewBox="0 0 430 340" role="img" aria-label="${state.lang==='en'?`${n} by ${n} square grid${shaded?' with a neutral shaded center target':''}.`:`Kisi persegi ${n} kali ${n}${shaded?' dengan target netral di tengah':''}.`}">${sh}${lines}</svg>`}
function renderSpatial(){const s=state.spatialStep;return `<div class="page">${navHead(sections[5])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'Reduce visual load by tracking contacts, hidden faces, and categories.':'Kurangi beban visual dengan melacak bidang kontak, sisi tersembunyi, dan kategori.'}</h3></div><div class="stage-grid"><div class="visual-stage">${cubeStackSVG()}</div><div class="focus-panel formal"><div class="label">${t('guide')}</div><p>${state.lang==='en'?'Five separate cubes have 30 faces. The efficient question is not “How many faces can I see?” but “How many face-to-face contacts hide two faces each?”':'Lima kubus terpisah memiliki 30 bidang. Pertanyaan efisien bukan “Berapa bidang yang terlihat?” tetapi “Berapa kontak antarkubus yang masing-masing menyembunyikan dua bidang?”'}</p><div class="prediction-grid"><button data-contact="3">3</button><button data-contact="4">4</button><button data-contact="5">5</button></div>${s?`<div class="face-ledger"><div><strong>30</strong>${state.lang==='en'?'separate faces':'bidang terpisah'}</div><div><strong>4</strong>${state.lang==='en'?'contacts':'kontak'}</div><div><strong>−8</strong>${state.lang==='en'?'hidden faces':'bidang tersembunyi'}</div></div>`:''}</div></div><div class="panel"><div class="label">${state.lang==='en'?'COUNT THROUGH GEOMETRY':'HITUNG MELALUI GEOMETRI'}</div><div class="stage-grid"><div class="visual-stage">${gridSVG(3,false)}</div><div><h3>${state.lang==='en'?'Do not scan randomly. Classify by size.':'Jangan memindai secara acak. Kelompokkan berdasarkan ukuran.'}</h3><p>${state.lang==='en'?'For a 3×3 square grid, count 1×1, 2×2, then 3×3 squares. A size table is a proof that no case was missed or duplicated.':'Untuk kisi persegi 3×3, hitung persegi 1×1, 2×2, lalu 3×3. Tabel berdasarkan ukuran menjadi bukti bahwa tidak ada kasus yang terlewat atau terhitung dua kali.'}</p>${quickAnswer('inlineF4',['14'],state.lang==='en'?'Counts by size: 9, 4, 1.':'Banyaknya berdasarkan ukuran: 9, 4, 1.')}</div></div></div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'In 3D, counting only the faces visible from one camera angle is unreliable. In visual counting, scanning without categories makes omissions and duplicates hard to detect.':'Pada bangun 3D, menghitung hanya bidang yang terlihat dari satu sudut pandang tidak dapat diandalkan. Pada hitung visual, memindai tanpa kategori membuat kasus terlewat atau ganda sulit dideteksi.'}</p></div></div>${navFoot()}</div>`}

function angleSVG(){const show=state.angleStep>0;return `<svg viewBox="0 0 720 360" role="img" aria-label="${state.lang==='en'?'Isosceles angle configuration with given equal-side marks and 24 degree angle.':'Konfigurasi sudut sama kaki dengan tanda sisi sama panjang dan sudut 24 derajat.'}"><polyline points="70,275 330,55 520,275" fill="none" stroke="#31596b" stroke-width="3"/><line x1="220" y1="148" x2="610" y2="325" stroke="#278a93" stroke-width="3"/><line x1="70" y1="275" x2="560" y2="275" stroke="#31596b" stroke-width="3"/><text x="55" y="295">P</text><text x="330" y="45">Q</text><text x="522" y="295">R</text><text x="430" y="295">B</text><text x="205" y="145">A</text><text x="617" y="338">C</text><text x="568" y="315" class="given">24°</text><line x1="173" y1="180" x2="184" y2="194" stroke="#6d49a8" stroke-width="4"/><line x1="423" y1="171" x2="410" y2="183" stroke="#6d49a8" stroke-width="4"/><line x1="468" y1="274" x2="468" y2="258" stroke="#d97706" stroke-width="4"/><line x1="550" y1="298" x2="558" y2="283" stroke="#d97706" stroke-width="4"/>${show?`<text x="482" y="315" class="derived">24°</text><text x="492" y="256" class="derived">48°</text><text x="292" y="87" class="derived">84°</text>`:''}<text x="254" y="132" class="muted">PQ = QR</text><text x="468" y="334" class="muted">BR = RC</text></svg>`}
function renderHidden(){return `<div class="page">${navHead(sections[6])}<div class="learn-cycle"><div class="focus-panel intuition"><div class="label">${t('mainIdea')}</div><h3>${state.lang==='en'?'Infer structure from the marks before hunting for a formula.':'Tarik hubungan dari tanda-tanda pada gambar sebelum mencari rumus.'}</h3></div><div class="stage-grid"><div class="visual-stage">${angleSVG()}<div class="micro-actions"><button data-angle>${state.angleStep?t('reset'):(state.lang==='en'?'Mark implied equal angles':'Tandai sudut-sudut sama yang tersirat')}</button></div></div><div class="focus-panel formal"><div class="label">${t('guide')}</div><p>${state.lang==='en'?'Equal sides imply equal base angles. Start inside triangle BRC, then use the straight line at R, then transfer the new angle into isosceles triangle PQR.':'Sisi sama panjang menghasilkan sudut alas yang sama. Mulai dari segitiga BRC, lalu gunakan garis lurus di R, kemudian bawa sudut yang diperoleh ke segitiga sama kaki PQR.'}</p>${state.angleStep?`<p>${state.lang==='en'?'The useful values propagate through the picture: 24° → 48° → 84°. Only then finish triangle AQC.':'Nilai yang berguna merambat melalui gambar: 24° → 48° → 84°. Baru setelah itu selesaikan segitiga AQC.'}</p>`:''}</div></div><div class="focus-panel turn"><div class="label">${t('yourTurn')}</div><p>${state.lang==='en'?'Using the same configuration, find angle QAC when angle C=24°.' :'Dengan konfigurasi yang sama, tentukan sudut QAC ketika sudut C=24°.'}</p>${quickAnswer('inlineA3',['72'],state.lang==='en'?'Mark both pairs of equal base angles first.':'Tandai kedua pasangan sudut alas yang sama terlebih dahulu.')}</div><div class="focus-panel trap"><div class="label">${t('trap')}</div><p>${state.lang==='en'?'Do not add an auxiliary line just because the diagram looks complicated. Here the given equal-side marks already contain the needed structure.':'Jangan menambahkan garis bantu hanya karena gambar terlihat rumit. Di sini tanda sisi sama panjang yang diberikan sudah memuat struktur yang dibutuhkan.'}</p></div></div>${navFoot()}</div>`}

function renderCompare(){const rows=[
 ['3D pyramid','reason directly in perspective','top view / face adjacency','change viewpoint'],['overlap area','trace irregular outside boundary','A + B − overlap','separate regions'],['paper folds','imagine final sheet at once','reverse one reflection at a time','symmetry is a mapping'],['angle diagram','search for a formula','mark implied equal angles','extract hidden relationships'],['visual counting','scan randomly','classify by size/type','organize to avoid duplicates']
];const rid=[['Piramida 3D','menalar langsung dari perspektif','tampak atas / hubungan sisi','ubah sudut pandang'],['Luas daerah tumpang tindih','menelusuri batas luar','A + B − daerah tumpang tindih','pisahkan daerah'],['Lipatan kertas','membayangkan hasil akhir sekaligus','balikkan satu pencerminan setiap kali','simetri adalah pemetaan'],['Diagram sudut','mencari rumus','tandai sudut sama yang tersirat','ambil hubungan tersembunyi'],['Hitung visual','memindai acak','kelompokkan berdasarkan ukuran/jenis','susun agar tidak ganda']];const data=state.lang==='en'?rows:rid;return `<div class="page">${navHead(sections[7])}<div class="panel"><div class="label">${t('mainIdea')}</div><h2>${state.lang==='en'?'Efficient visual reasoning changes the representation before it changes the arithmetic.':'Penalaran visual yang efisien mengubah representasi sebelum menambah hitungan.'}</h2><div style="overflow:auto"><table class="route-table"><thead><tr><th>${state.lang==='en'?'Problem surface':'Tampilan soal'}</th><th>${state.lang==='en'?'Natural but costly route':'Jalur alami tetapi mahal'}</th><th>${state.lang==='en'?'Visual restructuring':'Susun ulang visual'}</th><th>${state.lang==='en'?'Transferable lesson':'Pelajaran yang dapat dipakai ulang'}</th></tr></thead><tbody>${data.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>${mascot('sheet1_bottom_04.png', 'If you are calculating immediately, ask: “What can we change about the picture before we change the numbers?”', 'Kalau kamu langsung menghitung, tanyakan: “Apa yang bisa kita ubah pada gambar sebelum mengubah angka?”')}${navFoot()}</div>`}

const moveOptions=[
 {k:'redraw',en:'Redraw / change viewpoint',id:'Gambar ulang / ubah sudut pandang'},
 {k:'mark',en:'Mark relationships',id:'Tandai hubungan'},
 {k:'line',en:'Add an auxiliary line',id:'Tambah garis bantu'},
 {k:'split',en:'Split / decompose',id:'Pecah menjadi bagian'},
 {k:'subtract',en:'Enclose / subtract',id:'Bungkus / kurangi'},
 {k:'rearrange',en:'Rearrange pieces',id:'Susun ulang bagian'},
 {k:'symmetry',en:'Use symmetry',id:'Gunakan simetri'},
 {k:'small',en:'Try a smaller case',id:'Coba kasus yang lebih kecil'},
 {k:'count',en:'Count systematically',id:'Hitung secara sistematis'},
];
const recognition=[
 {id:'R1',q:{en:'Angle diagram: two pairs of equal sides are marked. What would you try FIRST?',id:'Diagram sudut: dua pasangan sisi sama panjang sudah ditandai. Apa yang kamu coba PERTAMA?'},good:['mark'],why:{en:'Turn equal sides into equal-angle information before calculating.',id:'Ubah sisi sama panjang menjadi informasi sudut sama sebelum menghitung.'}},
 {id:'R2',q:{en:'A cube has two cuboids removed from corners. What would best help track the new surface area?',id:'Sebuah kubus memiliki dua bagian balok yang dipotong dari sudutnya. Apa langkah terbaik untuk melacak luas permukaan baru?'},good:['split','rearrange'],why:{en:'Classify lost outside faces versus newly exposed faces.',id:'Kelompokkan bidang luar yang hilang dan bidang baru yang terbuka.'}},
 {id:'R3',q:{en:'A grid contains many squares of different sizes. What should come first?',id:'Sebuah kisi memiliki banyak persegi dengan ukuran berbeda. Apa yang harus dilakukan dulu?'},good:['count','small'],why:{en:'Organize by square size instead of scanning randomly.',id:'Susun berdasarkan ukuran persegi, bukan memindai secara acak.'}},
];
function renderRecognition(){return `<div class="page">${navHead(sections[8])}<div class="lesson-stack">${recognition.map((r,idx)=>`<div class="panel"><div class="label">${String.fromCharCode(65+idx)}</div><h3>${esc(i18n(r.q))}</h3><div class="move-grid">${moveOptions.map(m=>`<button data-rec="${r.id}" data-move="${m.k}" class="${state.moves[r.id]===m.k?'chosen':''}"><b>${esc(state.lang==='en'?m.en:m.id)}</b></button>`).join('')}</div>${state.moves[r.id]?`<div class="feedback-box show ${r.good.includes(state.moves[r.id])?'good':''}">${r.good.includes(state.moves[r.id])?(state.lang==='en'?'Strong first move. ':'Langkah pertama yang kuat. '):(state.lang==='en'?'Defensible only if you can show how it exposes structure. ':'Masih bisa dipertahankan jika kamu bisa menjelaskan bagaimana langkah itu membuka struktur. ')}${esc(i18n(r.why))}</div>`:''}</div>`).join('')}</div>${mascot('sheet2_top_02.png','More than one first move can be defensible. Reward the move that exposes structure and reduces work.','Lebih dari satu langkah pertama bisa masuk akal. Pilih yang paling membuka struktur dan mengurangi pekerjaan.')}${navFoot()}</div>`}

function renderMixed(){const prompts=[
 {en:'Overlap snapshot: Two familiar shapes overlap. Before calculating, state the three regions you would distinguish.',id:'Cuplikan tumpang tindih: Dua bangun familiar saling bertumpuk. Sebelum menghitung, sebutkan tiga daerah yang perlu dibedakan.'},
 {en:'Folding snapshot: A folded shape has one punch. State the order in which you would reverse the folds and what each unfold does to the current hole set.',id:'Cuplikan lipatan: Bangun terlipat memiliki satu lubang. Sebutkan urutan membuka lipatan dan apa yang dilakukan setiap pembukaan pada kumpulan lubang.'},
 {en:'Visual counting snapshot: A diagram contains small and large squares. State a counting organization that would convince someone you did not miss or double-count any.',id:'Cuplikan hitung visual: Diagram memiliki persegi kecil dan besar. Jelaskan susunan hitungan yang menunjukkan bahwa tidak ada yang terlewat atau terhitung dua kali.'}
];return `<div class="page">${navHead(sections[9])}<div class="lesson-stack">${prompts.map((p,i)=>`<div class="panel"><div class="label">${i+1}</div><h3>${esc(i18n(p))}</h3><textarea class="mix-note" data-mix="${i}" placeholder="${t('firstMove')}">${esc(state.answers['mix'+i]||'')}</textarea></div>`).join('')}<div class="panel green"><div class="label">${state.lang==='en'?'60-SECOND EXIT':'REFLEKSI 60 DETIK'}</div><ul><li>${state.lang==='en'?'What made a difficult diagram easier today?':'Apa yang membuat diagram sulit menjadi lebih mudah hari ini?'}</li><li>${state.lang==='en'?'Which visual move helped most?':'Langkah visual mana yang paling membantu?'}</li><li>${state.lang==='en'?'When an AMO picture feels overwhelming, what can you change before calculating?':'Saat gambar AMO terasa membingungkan, apa yang bisa diubah sebelum menghitung?'}</li></ul></div></div>${navFoot()}</div>`}

function quickAnswer(id,answers,hint){const val=state.answers[id]||'';const fb=state.feedback[id];return `<div class="workspace"><div class="answer-row"><input data-inline="${id}" value="${esc(val)}" inputmode="text" aria-label="${state.lang==='en'?'Answer':'Jawaban'}"><button class="primary-btn" data-inline-check="${id}" data-inline-answers="${esc(answers.join('|'))}">${t('check')}</button></div>${fb?`<div class="feedback-box show ${fb.ok?'good':'bad'}">${fb.ok?t('correct'):t('wrong')} ${!fb.ok?esc(hint):''}</div>`:''}</div>`}
function passes(p){return p.difficulty===state.level}
function roomTitle(r){const map={A:{en:'A · VISUALIZE / REDRAW',id:'A · LIHAT ULANG / GAMBAR ULANG'},B:{en:'B · DECOMPOSE',id:'B · PECAH MENJADI BAGIAN'},C:{en:'C · RECONSTRUCT / REARRANGE',id:'C · SUSUN ULANG'},D:{en:'D · USE SYMMETRY',id:'D · GUNAKAN SIMETRI'},E:{en:'E · SPATIAL REASONING',id:'E · PENALARAN RUANG'},F:{en:'F · COUNT THROUGH GEOMETRY',id:'F · HITUNG MELALUI GEOMETRI'}};return i18n(map[r])}
function currentProblem(){const pool=bank.filter(x=>x.room===state.practiceRoom&&passes(x));if(!pool.length)return null;state.practiceIndex=Math.max(0,Math.min(state.practiceIndex,pool.length-1));return pool[state.practiceIndex]}
function pyramidNeutralSVG(){const oldView=state.visualize.view,oldSel=state.visualize.selected;state.visualize.view='perspective';state.visualize.selected=[];const out=pyramidSVG();state.visualize.view=oldView;state.visualize.selected=oldSel;return out}
function angleNeutralSVG(){const old=state.angleStep;state.angleStep=0;const out=angleSVG();state.angleStep=old;return out}
function overlapNeutralSVG(){const old=state.decompStep;state.decompStep=0;const out=overlapSVG();state.decompStep=old;return out}
function reconstructNeutralVisual(){const old=state.reconstructStep;state.reconstructStep=0;const out=reconstructVisual();state.reconstructStep=old;return out}
function problemVisual(p){
 if(p.id==='A1')return `<div class="visual-stage">${pyramidNeutralSVG()}</div>`;
 if(p.id==='A3')return `<div class="visual-stage">${angleNeutralSVG()}</div>`;
 if(p.id==='A4')return `<div class="visual-stage">${nestedSquareSVG(6,5)}</div>`;
 if(p.id==='A6')return `<div class="visual-stage">${fractionBarSVG()}</div>`;
 if(p.id==='B1')return `<div class="visual-stage">${overlapNeutralSVG()}</div>`;
 if(p.id==='B2')return `<div class="visual-stage">${simpleOverlapVisual('B2')}</div>`;
 if(p.id==='B3')return `<div class="visual-stage">${perimeterOverlapSVG()}</div>`;
 if(p.id==='B4')return `<div class="visual-stage">${simpleOverlapVisual('B4')}</div>`;
 if(p.id==='B6')return `<div class="visual-stage">${gluedBricksSVG()}</div>`;
 if(p.id==='C1')return `<div class="visual-stage">${cubeRearrangeNeutralSVG()}</div>`;
 if(p.id==='C2')return `<div class="visual-stage">${steelReshapeSVG()}</div>`;
 if(p.id==='C3')return `<div class="visual-stage">${foldAreaSVG()}</div>`;
 if(p.id==='C4')return `<div class="visual-stage">${trianglePackSVG()}</div>`;
 if(p.id==='D1')return `<div class="visual-stage">${foldTriangleSVG(false)}</div>`;
 if(p.id==='D2')return `<div class="visual-stage">${coordinateReflectSVG()}</div>`;
 if(p.id==='D5')return `<div class="visual-stage">${twoFoldSquareSVG()}</div>`;
 if(p.id==='E1')return `<div class="visual-stage">${cubeStackSVG()}</div>`;
 if(p.id==='E2')return `<div class="visual-stage">${cornerCubeDiagramSVG()}</div>`;
 if(p.id==='E4')return `<div class="visual-stage">${reshapeVolumeSVG()}</div>`;
 if(p.id==='F1')return `<div class="visual-stage">${latticeSVG()}</div>`;
 if(p.id==='F4')return `<div class="visual-stage">${gridSVG(3,false)}</div>`;
 if(p.id==='F6')return `<div class="visual-stage">${gridSVG(5,true)}</div>`;
 return ''
}
function fractionBarSVG(){return `<svg viewBox="0 0 620 250" role="img" aria-label="${state.lang==='en'?'A neutral 12-part bar comparing one quarter and one third. The total number of candles is not shown.':'Batang netral 12 bagian yang membandingkan seperempat dan sepertiga. Jumlah seluruh lilin tidak ditampilkan.'}"><g transform="translate(60 60)">${Array.from({length:12},(_,i)=>`<rect x="${i*42}" y="0" width="42" height="52" fill="${i<3?'#dff1f4':'#fff'}" stroke="#78909a"/>`).join('')}<text x="0" y="-16" class="given">1/4</text>${Array.from({length:12},(_,i)=>`<rect x="${i*42}" y="82" width="42" height="52" fill="${i<4?'#efe7fa':'#fff'}" stroke="#78909a"/>`).join('')}<text x="0" y="72" class="given">1/3</text><text x="147" y="180" class="given">+5 ${state.lang==='en'?'candles':'lilin'}</text></g></svg>`}
function perimeterOverlapSVG(){return `<svg viewBox="0 0 620 300" role="img" aria-label="${state.lang==='en'?'Two 6 by 10 rectangles overlap in a rectangular region with unknown whole-number side lengths.':'Dua persegi panjang 6 kali 10 saling bertumpuk pada daerah persegi panjang dengan panjang sisi bilangan cacah yang belum diketahui.'}"><rect x="90" y="100" width="330" height="105" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="240" y="60" width="105" height="205" fill="#f1ebfb" fill-opacity=".85" stroke="#6d49a8" stroke-width="3"/><rect x="240" y="100" width="105" height="105" fill="#fff0ce"/><text x="120" y="88" class="given">6 × 10</text><text x="360" y="50" class="given">6 × 10</text><text x="292" y="158" text-anchor="middle" class="target">${state.lang==='en'?'overlap ?':'tumpang tindih ?'}</text></svg>`}
function gluedBricksSVG(){return `<svg viewBox="0 0 620 280" role="img" aria-label="${state.lang==='en'?'Two identical 6 by 6 by 2 bricks touching along a 2 by 6 face. No surface-area result is shown.':'Dua balok identik 6 kali 6 kali 2 bersentuhan pada bidang 2 kali 6. Hasil luas permukaan tidak ditampilkan.'}"><rect x="80" y="95" width="210" height="110" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="290" y="95" width="210" height="110" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><line x1="290" y1="95" x2="290" y2="205" stroke="#d9467d" stroke-width="5" stroke-dasharray="8 6"/><text x="185" y="150" text-anchor="middle" class="given">6 × 6 × 2</text><text x="395" y="150" text-anchor="middle" class="given">6 × 6 × 2</text><text x="310" y="235" text-anchor="middle" class="muted">${state.lang==='en'?'contact face = 2 × 6':'bidang kontak = 2 × 6'}</text></svg>`}
function cubeRearrangeNeutralSVG(){return `<svg viewBox="0 0 650 300" role="img" aria-label="${state.lang==='en'?'A 4 by 4 by 4 cube is cut into two equal solids; final dimensions are not shown.':'Kubus 4 kali 4 kali 4 dipotong menjadi dua bagian sama; ukuran akhir belum ditampilkan.'}"><rect x="70" y="70" width="160" height="160" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><line x1="70" y1="150" x2="230" y2="150" stroke="#d97706" stroke-width="3" stroke-dasharray="8 6"/><text x="150" y="255" text-anchor="middle" class="given">4 × 4 × 4</text><text x="300" y="155" class="derived">→</text><rect x="360" y="80" width="100" height="135" fill="#eef6f8" stroke="#31596b" stroke-width="3"/><rect x="475" y="80" width="100" height="135" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="468" y="245" text-anchor="middle" class="target">${state.lang==='en'?'rebuild ?':'susun ulang ?'}</text></svg>`}
function steelReshapeSVG(){return `<svg viewBox="0 0 650 285" role="img" aria-label="${state.lang==='en'?'A 270 by 100 by 64 steel cuboid is reshaped into a cube with unknown side.':'Balok baja 270 kali 100 kali 64 dibentuk ulang menjadi kubus dengan sisi yang belum diketahui.'}"><rect x="55" y="90" width="250" height="105" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><text x="180" y="148" text-anchor="middle" class="given">270 × 100 × 64</text><text x="325" y="145" class="derived">→</text><rect x="420" y="70" width="135" height="135" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="487" y="145" text-anchor="middle" class="target">s = ?</text><text x="315" y="245" text-anchor="middle" class="muted">${state.lang==='en'?'same steel — volume preserved':'baja yang sama — volume tetap'}</text></svg>`}
function foldAreaSVG(){return `<svg viewBox="0 0 650 275" role="img" aria-label="${state.lang==='en'?'Unknown original rectangle folded twice to a 6 by 6 square.':'Persegi panjang awal yang belum diketahui dilipat dua kali menjadi persegi 6 kali 6.'}"><rect x="50" y="75" width="210" height="125" fill="#f8fbfc" stroke="#31596b" stroke-width="3"/><text x="155" y="143" text-anchor="middle" class="target">${state.lang==='en'?'original area ?':'luas awal ?'}</text><text x="285" y="143" class="derived">→ ½ → ½ →</text><rect x="440" y="78" width="120" height="120" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="500" y="145" text-anchor="middle" class="given">6 × 6</text></svg>`}
function trianglePackSVG(){const baseX=45;return `<svg viewBox="0 0 680 260" role="img" aria-label="${state.lang==='en'?'Four separate right triangles with legs 1 by 4, 2 by 4, 3 by 4, and 4 by 4; no containing rectangle is shown.':'Empat segitiga siku-siku terpisah dengan kaki 1 kali 4, 2 kali 4, 3 kali 4, dan 4 kali 4; persegi panjang pembungkus belum ditampilkan.'}">${[1,2,3,4].map((h,i)=>{const x=baseX+i*150,y=205;return `<polygon points="${x},${y} ${x+110},${y} ${x},${y-h*34}" fill="#e9f6fa" stroke="#31596b" stroke-width="2.5"/><text x="${x+35}" y="235" class="given">${h} × 4</text>`}).join('')}</svg>`}
function twoFoldSquareSVG(){return `<svg viewBox="0 0 650 270" role="img" aria-label="${state.lang==='en'?'A square sheet is folded vertically and horizontally; one punch is away from both fold lines. Final hole count is hidden.':'Kertas persegi dilipat vertikal dan horizontal; satu lubang berada jauh dari kedua garis lipatan. Jumlah lubang akhir disembunyikan.'}"><rect x="70" y="45" width="180" height="180" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/><line x1="160" y1="45" x2="160" y2="225" stroke="#8aa0aa" stroke-dasharray="8 6"/><line x1="70" y1="135" x2="250" y2="135" stroke="#8aa0aa" stroke-dasharray="8 6"/><circle cx="205" cy="90" r="7" fill="white" stroke="#d9467d" stroke-width="4"/><text x="350" y="130" class="target">${state.lang==='en'?'unfold → ? holes':'buka lipatan → ? lubang'}</text></svg>`}
function cornerCubeDiagramSVG(){return `<svg viewBox="0 0 620 300" role="img" aria-label="${state.lang==='en'?'Schematic 4 by 4 by 4 cube with one corner unit marked for removal; no new surface area is shown.':'Skema kubus 4 kali 4 kali 4 dengan satu kubus satuan di sudut ditandai untuk diambil; luas permukaan baru tidak ditampilkan.'}"><polygon points="150,80 360,80 440,135 230,135" fill="#eef6f8" stroke="#31596b" stroke-width="3"/><polygon points="150,80 230,135 230,260 150,205" fill="#dff1f4" stroke="#31596b" stroke-width="3"/><polygon points="230,135 440,135 440,260 230,260" fill="#f8fbfc" stroke="#31596b" stroke-width="3"/><polygon points="150,80 202,80 222,94 170,94" fill="#f5d9e4" stroke="#d9467d" stroke-width="2"/><text x="320" y="282" text-anchor="middle" class="given">4 × 4 × 4</text><text x="180" y="58" class="muted">${state.lang==='en'?'corner unit':'kubus sudut'}</text></svg>`}
function nestedSquareSVG(a,b){return `<svg viewBox="0 0 420 320" role="img" aria-label="${state.lang==='en'?`A ${a} by ${a} square containing a ${b} by ${b} square. No area answer is shown.`:`Persegi ${a} kali ${a} yang memuat persegi ${b} kali ${b}. Jawaban luas tidak ditampilkan.`}"><rect x="70" y="40" width="260" height="260" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/><rect x="92" y="62" width="216" height="216" fill="none" stroke="#8aa0aa" stroke-width="3" stroke-dasharray="9 6"/><text x="200" y="28" text-anchor="middle" class="given">${a}</text><text x="200" y="178" text-anchor="middle" class="given">${b}</text></svg>`}
function simpleOverlapVisual(id){if(id==='B2')return `<svg viewBox="0 0 620 270"><rect x="70" y="90" width="330" height="90" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="220" y="90" width="330" height="90" fill="#f1ebfb" fill-opacity=".8" stroke="#6d49a8" stroke-width="3"/><rect x="220" y="90" width="180" height="90" fill="#fff0ce" fill-opacity=".8"/><text x="155" y="78" class="given">13 × 17</text><text x="455" y="78" class="given">13 × 17</text><text x="310" y="218" text-anchor="middle" class="given">${state.lang==='en'?'union length = 31':'panjang gabungan = 31'}</text><text x="310" y="145" text-anchor="middle" class="target">?</text></svg>`;if(id==='B4')return `<svg viewBox="0 0 620 280"><rect x="90" y="70" width="260" height="140" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="270" y="70" width="260" height="140" fill="#f1ebfb" fill-opacity=".8" stroke="#6d49a8" stroke-width="3"/><rect x="270" y="70" width="80" height="140" fill="#fff0ce"/><text x="310" y="145" text-anchor="middle" class="given">4 cm²</text><text x="310" y="242" text-anchor="middle" class="given">${state.lang==='en'?'total non-overlap = 12 cm²':'total bagian yang tidak saling bertumpuk = 12 cm²'}</text></svg>`;return overlapNeutralSVG()}
function coordinateReflectSVG(){return `<svg viewBox="0 0 520 330" role="img" aria-label="${state.lang==='en'?'Coordinate grid with triangle ABC and mirror line x equals 5. Reflected points are not shown.':'Kisi koordinat dengan segitiga ABC dan garis cermin x sama dengan 5. Titik hasil pencerminan belum ditampilkan.'}"><g stroke="#d8e2e5" stroke-width="1">${Array.from({length:11},(_,i)=>`<line x1="${50+i*40}" y1="30" x2="${50+i*40}" y2="290"/><line x1="50" y1="${290-i*26}" x2="450" y2="${290-i*26}"/>`).join('')}</g><line x1="250" y1="30" x2="250" y2="290" stroke="#d9467d" stroke-width="3" stroke-dasharray="8 6"/><text x="258" y="48" class="given">x=5</text><polygon points="90,264 130,186 210,238" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><text x="78" y="275">A</text><text x="125" y="176">B</text><text x="214" y="247">C</text></svg>`}
function reshapeVolumeSVG(){return `<svg viewBox="0 0 620 270"><rect x="60" y="85" width="230" height="110" rx="6" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><text x="175" y="145" text-anchor="middle" class="given">40 × 25 × 8</text><text x="315" y="145" text-anchor="middle" class="derived">→</text><rect x="390" y="75" width="130" height="130" rx="6" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="455" y="145" text-anchor="middle" class="target">s = ?</text><text x="310" y="235" text-anchor="middle" class="muted">${state.lang==='en'?'same material → same volume':'bahan sama → volume sama'}</text></svg>`}
function cornerCubeSVG(){return `<svg viewBox="0 0 520 300"><rect x="120" y="50" width="230" height="230" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="120" y="50" width="58" height="58" fill="#fff" stroke="#d9467d" stroke-width="2" stroke-dasharray="6 5"/><text x="235" y="295" text-anchor="middle" class="muted">${state.lang==='en'?'corner unit cube removed':'kubus satuan di sudut diambil'}</text></svg>`}
function latticeSVG(){return `<svg viewBox="0 0 430 340"><g stroke="#6f8791" stroke-width="2">${[95,195,295].map(x=>`<line x1="${x}" y1="65" x2="${x}" y2="265"/>`).join('')}${[65,165,265].map(y=>`<line x1="95" y1="${y}" x2="295" y2="${y}"/>`).join('')}</g>${[95,195,295].flatMap(x=>[65,165,265].map(y=>`<circle cx="${x}" cy="${y}" r="5" fill="#31596b"/>`)).join('')}<text x="80" y="288" class="given">${state.lang==='en'?'START':'MULAI'}</text><text x="286" y="48" class="given">${state.lang==='en'?'END':'AKHIR'}</text></svg>`}
function renderPractice(){const rooms=['A','B','C','D','E','F'];const p=currentProblem();return `<div class="page">${navHead(sections[10])}<div class="panel"><div class="label">${t('practice')}</div><p>${state.lang==='en'?'Phase 2 uses a focused source-grounded subset. Phase 3 will expand this to the full 55-problem ecosystem, Room G, Mixed Visual Takes, Stretch, Previous Problem, deeper hint ladders, and richer history.':'Fase 2 menggunakan subset terpilih yang berbasis sumber. Fase 3 akan memperluasnya menjadi ekosistem 55 soal penuh, Ruang G, latihan visual campuran, pengayaan, soal sebelumnya, tangga petunjuk yang lebih dalam, dan riwayat yang lebih kaya.'}</p><div class="practice-nav">${rooms.map(r=>`<button class="${state.practiceRoom===r?'active':''}" data-room="${r}">${roomTitle(r)}</button>`).join('')}</div>${!p?`<div class="feedback-box show">${t('noLevel')}</div>`:renderProblem(p)}</div>${navFoot()}</div>`}
function renderProblem(p){const val=state.answers[p.id]||'',fb=state.feedback[p.id],move=state.moves[p.id]||'',hint=state.hints[p.id];return `<div class="problem-card"><div class="problem-meta"><span>${p.id}</span><span class="level-${p.difficulty}">${p.difficulty==='core'?t('core'):p.difficulty==='challenge'?t('challenge'):t('advanced')}</span><span>${p.time}</span></div><p class="problem-q">${esc(i18n(p.q))}</p>${problemVisual(p)}<div class="first-move-box"><label><strong>${t('firstMove')}</strong></label><textarea data-first-move="${p.id}" placeholder="${state.lang==='en'?'What would you change, mark, split, reflect, or organize first?':'Apa yang akan kamu ubah, tandai, pecah, cerminkan, atau susun terlebih dahulu?'}">${esc(move)}</textarea></div><div class="workspace"><div class="answer-row"><input data-answer="${p.id}" value="${esc(val)}" placeholder="${state.lang==='en'?'Answer':'Jawaban'}"><button class="primary-btn" data-check="${p.id}">${t('check')}</button><button class="soft-btn" data-hint="${p.id}">${t('hint')}</button></div>${hint?`<div class="hint-box">${esc(i18n(p.hint))}</div>`:''}${fb?`<div class="feedback-box show ${fb.ok?'good':'bad'}">${fb.ok?t('correct'):t('wrong')}${!fb.ok?' '+esc(i18n(p.trap)):''}</div>`:''}${fb&&fb.ok?`<div class="solution-box"><strong>${state.lang==='en'?'Solution structure:':'Struktur solusi:'}</strong> ${esc(i18n(p.solution))}</div>`:''}</div><div class="micro-actions"><button data-change>${t('change')}</button></div><div class="teacher-panel teacher-only"><strong>${t('teacherNotes')}</strong><p>${t('source')}: ${esc(p.source)} · ${t('type')}: ${esc(p.type)} · ${t('time')}: ${esc(p.time)}</p><p>${t('trap')}: ${esc(i18n(p.trap))}</p></div></div>`}

function render(){document.body.classList.toggle('teacher-mode',state.teacher);document.getElementById('brandTitle').textContent=t('brand');document.getElementById('brandSub').textContent=t('sub');document.getElementById('teacherPassBtn').textContent=state.teacher?t('teacherOn'):t('teacher');document.getElementById('teacherPassBtn').classList.toggle('active',state.teacher);document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.lang));document.querySelectorAll('.level-btn').forEach(b=>{b.classList.toggle('active',b.dataset.level===state.level);b.textContent=b.dataset.level==='core'?t('core'):b.dataset.level==='challenge'?t('challenge'):t('advanced')});document.documentElement.lang=state.lang==='id'?'id':'en';document.getElementById('footerProgress').textContent=`${state.completed.length}/${sections.length} ${t('progress')}`;let html;if(state.section<0)html=renderHome();else{switch(state.section){case 0:html=renderMap();break;case 1:html=renderVisualize();break;case 2:html=renderDecompose();break;case 3:html=renderReconstruct();break;case 4:html=renderSymmetry();break;case 5:html=renderSpatial();break;case 6:html=renderHidden();break;case 7:html=renderCompare();break;case 8:html=renderRecognition();break;case 9:html=renderMixed();break;case 10:html=renderPractice();break;default:state.section=-1;html=renderHome()}}document.getElementById('main').innerHTML=html;save();window.scrollTo({top:0,behavior:'auto'})}

// Home starts at -1 unless a saved section exists.
if(localStorage.getItem('amo3Visited')!=='1'){state.section=-1;localStorage.setItem('amo3Visited','1')}

document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-edge]');if(!b)return;
 if(b.matches('.lang-btn')){state.lang=b.dataset.lang;render();return}
 if(b.matches('.level-btn')){state.level=b.dataset.level;state.practiceIndex=0;render();return}
 if(b.id==='teacherPassBtn'){state.teacher=!state.teacher;render();return}
 if(b.id==='homeBtn'){state.section=-1;render();return}
 if(b.dataset.start!==undefined){state.section=0;render();return}
 if(b.dataset.open!==undefined){state.section=Number(b.dataset.open);render();return}
 if(b.dataset.nav){state.section+=b.dataset.nav==='next'?1:-1;render();return}
 if(b.dataset.complete!==undefined){if(!state.completed.includes(state.section))state.completed.push(state.section);else state.completed=state.completed.filter(x=>x!==state.section);render();return}
 if(b.dataset.view){state.visualize.view=b.dataset.view;render();return}
 if(b.dataset.edge){const id=b.dataset.edge;state.visualize.selected=state.visualize.selected.includes(id)?state.visualize.selected.filter(x=>x!==id):[...state.visualize.selected,id];render();return}
 if(b.dataset.checkPyramid!==undefined){checkPyramid();return}
 if(b.dataset.resetPyramid!==undefined){state.visualize.selected=[];render();return}
 if(b.dataset.decompNext!==undefined){state.decompStep=Math.min(3,state.decompStep+1);render();return}
 if(b.dataset.decompReset!==undefined){state.decompStep=0;render();return}
 if(b.dataset.reconstruct!==undefined){state.reconstructStep=state.reconstructStep?0:1;render();return}
 if(b.dataset.symReset!==undefined){state.symStep=0;render();return}
 if(b.dataset.symChoice){const c=b.dataset.symChoice;if(state.symStep===0){if(c==='last'){state.symStep=1;toast(state.lang==='en'?'Yes. Undo the most recent fold first.':'Ya. Buka lipatan paling baru terlebih dahulu.')}else toast(state.lang==='en'?'Use the reverse order of the folds.':'Gunakan urutan lipatan secara terbalik.')}else if(state.symStep===1){if(c==='reflect'){state.symStep=2;toast(state.lang==='en'?'Correct. A reflected partner appears.':'Benar. Muncul pasangan hasil pencerminan.')}else toast(state.lang==='en'?'An unfold reflects the current hole across the fold line.':'Membuka lipatan mencerminkan lubang terhadap garis lipatan.')}else if(state.symStep===2&&c==='reveal'){state.symStep=3}render();return}
 if(b.dataset.contact){if(b.dataset.contact==='4'){state.spatialStep=1;toast(state.lang==='en'?'Yes — 4 contacts hide 8 faces.':'Ya — 4 kontak menyembunyikan 8 bidang.');render()}else toast(state.lang==='en'?'Recheck every face-to-face contact, including the rear cube.':'Cek lagi semua bidang yang bersentuhan, termasuk kubus di belakang.');return}
 if(b.dataset.angle!==undefined){state.angleStep=state.angleStep?0:1;render();return}
 if(b.dataset.rec){state.moves[b.dataset.rec]=b.dataset.move;render();return}
 if(b.dataset.inlineCheck){const id=b.dataset.inlineCheck,answers=b.dataset.inlineAnswers.split('|');const input=document.querySelector(`[data-inline="${id}"]`);state.answers[id]=input?.value||'';state.feedback[id]={ok:answerOK(state.answers[id],answers)};render();return}
 if(b.dataset.room){state.practiceRoom=b.dataset.room;state.practiceIndex=0;render();return}
 if(b.dataset.check){const id=b.dataset.check,p=bank.find(x=>x.id===id);const input=document.querySelector(`[data-answer="${id}"]`);const moveBox=document.querySelector(`[data-first-move="${id}"]`);state.answers[id]=input?.value||'';state.moves[id]=moveBox?.value||state.moves[id]||'';if(!String(state.moves[id]).trim()){toast(t('firstMoveNeed'));return}state.feedback[id]={ok:answerOK(state.answers[id],p.answers)};render();return}
 if(b.dataset.hint){state.hints[b.dataset.hint]=true;render();return}
 if(b.dataset.change!==undefined){const pool=bank.filter(x=>x.room===state.practiceRoom&&passes(x));if(pool.length<2){toast(state.lang==='en'?'No other Phase-2 problem in this room and level yet.':'Belum ada soal Fase 2 lain pada ruang dan level ini.');return}state.practiceIndex=(state.practiceIndex+1)%pool.length;render();return}
});

document.addEventListener('input',e=>{if(e.target.dataset.firstMove)state.moves[e.target.dataset.firstMove]=e.target.value;if(e.target.dataset.answer)state.answers[e.target.dataset.answer]=e.target.value;if(e.target.dataset.inline)state.answers[e.target.dataset.inline]=e.target.value;if(e.target.dataset.mix!==undefined)state.answers['mix'+e.target.dataset.mix]=e.target.value});
render();
